using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class AudioAnalysisOperations
{
    private static Settings Decode(AudioStream stream,int rate,double start,double duration,double limit){using var cache=new AudioSourceCacheOperations();return cache.decode(stream,rate,start,duration,limit);}
    public string silence_source_error(Variant value)
    {
        if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is AudioStream stream){double length=stream.GetLength();return !double.IsFinite(length)||length<=0||length>600?"Dialogue analysis requires a nonempty source of at most 600 seconds. Render or split it to a shorter source first.":"";}if(value.VariantType!=Variant.Type.String||value.AsString().Length==0)return "Missing audio source.";string path=value.AsString();if(path.GetExtension().ToLowerInvariant()=="wav"){using var pcm=new AudioPcmFileOperations();var info=pcm.inspect(path);if(!info.TryGetValue("error",out var error)||error.AsString().Length>0)return "Dialogue analysis requires supported mono/stereo PCM WAV. "+(info.TryGetValue("error",out var detail)?detail.AsString():"Invalid WAV metadata.");double seconds=info["duration"].AsDouble();return !double.IsFinite(seconds)||seconds<=0||seconds>86400?"PCM dialogue sources must be nonempty and at most 24 hours long.":"";}using var file=Godot.FileAccess.Open(path,Godot.FileAccess.ModeFlags.Read);if(file==null)return "Missing or unreadable audio source.";ulong bytes=file.GetLength();return bytes==0||bytes>64*1024*1024?"Non-PCM dialogue analysis requires a source file of at most 64 MiB and at most 600 seconds. Use mono/stereo PCM WAV for bounded long-source analysis.":"";
    }
    public Settings analyze_source(Variant value,double thresholdDb,double minimumSilence,RefCounted? job,double start,double duration)
    {
        if(!double.IsFinite(thresholdDb)||thresholdDb< -120||thresholdDb>0||!double.IsFinite(minimumSilence)||minimumSilence<=0||minimumSilence>600)return Failure("Invalid silence detector settings.");if(!double.IsFinite(start)||start<0||!double.IsFinite(duration)||(duration!=-1&&duration<=0))return Failure("Invalid analysis source window.");if(Cancelled(job))return Failure("Cancelled.");if(value.VariantType==Variant.Type.String&&value.AsString().GetExtension().ToLowerInvariant()=="wav"){using var pcm=new AudioPcmFileOperations();var info=pcm.inspect(value.AsString());if(!info.TryGetValue("error",out var problem)||problem.AsString().Length>0)return Failure("Dialogue analysis requires supported mono/stereo PCM WAV. "+(info.TryGetValue("error",out var detail)?detail.AsString():"Invalid WAV metadata."));return analyze_pcm_file(value.AsString(),info,thresholdDb,minimumSilence,job,start,duration);}string error=silence_source_error(value);if(error.Length>0)return Failure(error);var signature=value.VariantType==Variant.Type.String?analysis_file_signature(value.AsString()):new Settings();if(value.VariantType==Variant.Type.String&&signature.Count==0)return Failure("Missing or unreadable audio source.");var stream=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("source",value,Variant.From(job)).As<AudioStream>();if(Cancelled(job))return Failure("Cancelled.");if(stream==null)return Failure("Missing or unreadable audio source.");error=silence_source_error(stream);if(error.Length>0)return Failure(error);if(start>=stream.GetLength()||(duration>0&&start+duration>stream.GetLength()+.0001))return Failure("The selected source window extends beyond the recording.");var result=analyze(stream,thresholdDb,minimumSilence,job);if(result.TryGetValue("error",out var resultError)&&resultError.AsString().Length>0)return result;if(Cancelled(job))return Failure("Cancelled.");if(value.VariantType==Variant.Type.String&&!signature.RecursiveEqual(analysis_file_signature(value.AsString())))return Failure("The source changed during analysis. Analyze it again.");if(result["silences"].AsGodotArray().Count>2048)return Failure("More than 2048 quiet regions were detected. Increase the minimum pause duration and analyze again.");result["analyzed_start"]=0.0;result["analyzed_end"]=result["duration"];result["analyzed_duration"]=result["duration"];result["envelope_start"]=0.0;result["method"]="Whole short-source decode";result["tempo_limited"]=false;result["tempo_duration"]=result["duration"];result["windowed"]=false;result["source_signature"]=signature;return result;
    }
    public Settings analyze(AudioStream stream,double thresholdDb,double minimumSilence,RefCounted? job)
    {
        if(!double.IsFinite(thresholdDb)||thresholdDb< -120||thresholdDb>0||!double.IsFinite(minimumSilence)||minimumSilence<=0||minimumSilence>600)return Failure("Invalid silence detector settings.");if(Cancelled(job))return Failure("Cancelled.");string problem=silence_source_error(stream);if(problem.Length>0)return Failure(problem);var decoded=Decode(stream,12000,0,-1,600);if(decoded["error"].AsString().Length>0)return decoded;var samples=decoded["samples"].AsVector2Array();if(samples.Length==0)return new Settings {["error"]="Empty recording.",["transients"]=new GArray(),["silences"]=new GArray(),["peak_db"]=-120,["rms_db"]=-120,["tempo"]=0,["confidence"]=0};const int rate=12000,block=120;var energies=new List<float>();double peak=0,sumSquared=0;int total=0;for(int start=0;start<samples.Length;start+=block){double power=0;int count=Math.Min(block,samples.Length-start);for(int index=start;index<start+count;index++){var sample=samples[index];peak=Math.Max(peak,Math.Max(Math.Abs(sample.X),Math.Abs(sample.Y)));power+=((double)sample.X*sample.X+(double)sample.Y*sample.Y)*.5;}energies.Add((float)Math.Sqrt(power/Math.Max(1,count)));sumSquared+=power;total+=count;if(job!=null&&start%120000==0){if(Cancelled(job))return Failure("Cancelled.");Progress(job,(double)start/samples.Length,"Analyzing audio");}}
        var transients=new Godot.Collections.Array<double>();var silences=new Godot.Collections.Array<Settings>();double threshold=Mathf.DbToLinear(thresholdDb),previous=0,average=0;int silenceStart=-1,lastAttack=-100;var onset=new float[energies.Count];for(int index=0;index<energies.Count;index++){double energy=energies[index];average=average*.92+energy*.08;double flux=Math.Max(0,energy-previous);onset[index]=(float)flux;if(energy>threshold*2&&flux>Math.Max(.012,average*.6)&&index-lastAttack>=7){transients.Add(index*.01);lastAttack=index;}if(energy<threshold){if(silenceStart<0)silenceStart=index;}else if(silenceStart>=0){if((index-silenceStart)*.01>=minimumSilence)silences.Add(new Settings {["start"]=silenceStart*.01,["end"]=index*.01});silenceStart=-1;}previous=energy;}if(silenceStart>=0&&(energies.Count-silenceStart)*.01>=minimumSilence)silences.Add(new Settings {["start"]=silenceStart*.01,["end"]=(double)samples.Length/rate});double best=0,second=0;int bestLag=0;for(int lag=33;lag<=100;lag++){double correlation=0;for(int index=lag;index<onset.Length;index++)correlation+=(double)onset[index]*onset[index-lag];if(correlation>best){second=best;best=correlation;bestLag=lag;}else if(correlation>second)second=correlation;}return new Settings {["error"]="",["transients"]=transients,["silences"]=silences,["peak_db"]=Mathf.LinearToDb(Math.Max(.000001,peak)),["rms_db"]=Mathf.LinearToDb(Math.Max(.000001,Math.Sqrt(sumSquared/Math.Max(1,total)))),["tempo"]=bestLag>0?6000.0/bestLag:0,["confidence"]=Math.Clamp((best-second)/Math.Max(.000001,best)*8,0,1),["duration"]=(double)samples.Length/rate,["envelope"]=energies.ToArray(),["envelope_rate"]=100};
    }
    public Settings spectrogram(AudioStream stream,double start,double duration,int columns,int rows,RefCounted? job)
    {
        const int rate=12000;var decoded=Decode(stream,rate,start,Math.Min(duration,60),60);if(decoded["error"].AsString().Length>0)return decoded;var samples=decoded["samples"].AsVector2Array();var image=Image.CreateEmpty(columns,rows,false,Image.Format.Rgb8);for(int x=0;x<columns;x++){if(Cancelled(job)){image.Dispose();return Failure("Cancelled.");}var magnitudes=spectrum(samples,(int)((double)x/columns*samples.Length),1024);for(int y=0;y<rows;y++){double hz=30*Math.Pow(200,(double)(rows-1-y)/Math.Max(1,rows-1));int bin=Math.Clamp((int)(hz*1024/rate),0,magnitudes.Length-1);double value=Math.Clamp((Mathf.LinearToDb(Math.Max(.000001,magnitudes[bin]))+85)/85,0,1);image.SetPixel(x,y,Color.FromHsv((float)(.68-value*.62),.9f,(float)Math.Clamp(value*1.4,0,1)));}Progress(job,(double)x/columns,"Building spectrogram");}return new Settings {["image"]=image,["error"]="",["start"]=start,["duration"]=Math.Min(duration,60),["rate"]=rate};
    }
}
